contracts/LoyaltyPoints.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title LoyaltyPoints
 * @dev Soulbound participation points. Multiplier from KREX tier (hardcoded thresholds).
 * @notice Only authorized callers (e.g. FeeRouter) can call awardPointsWithMultiplier.
 */
contract LoyaltyPoints is Ownable {
    uint256 public constant BPS = 10000;

    struct LoyaltyData {
        uint256 totalPoints;
        uint256 participationDays;
        uint256 lastActivity;
        uint256 streakDays;
    }

    mapping(address => LoyaltyData) public userLoyalty;
    mapping(string => uint256) public actionPoints;
    mapping(string => uint256) public pointsPer1iKAS; // e.g. "dapp-payment" => 100 XP per 1 iKAS
    uint256 public streakInterval = 86400;

    mapping(address => bool) public authorizedCallers;
    IERC20 public krexToken; // optional: set to read balance for tier multiplier

    // Hardcoded KREX tier thresholds (18 decimals, same as tKREX/KREX)
    uint256 private constant TIER1_MIN = 1 * 10**18;
    uint256 private constant TIER2_MIN = 10_000_000 * 10**18;
    uint256 private constant TIER3_MIN = 50_000_000 * 10**18;
    uint256 private constant TIER4_MIN = 100_000_000 * 10**18;

    event PointsAwarded(address indexed user, string actionType, uint256 points, uint256 totalPoints, uint256 timestamp);
    event StreakUpdated(address indexed user, uint256 streakDays, uint256 timestamp);
    event ActionPointsUpdated(string actionType, uint256 oldPoints, uint256 newPoints);
    event AuthorizedCallerSet(address indexed caller, bool allowed);
    event KREXTokenSet(address indexed token);

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender], "LoyaltyPoints: Unauthorized");
        _;
    }

    constructor() Ownable(msg.sender) {
        actionPoints["vote"] = 10;
        actionPoints["proposal"] = 50;
        actionPoints["payment"] = 5;
        actionPoints["dapp-payment"] = 5;
        pointsPer1iKAS["dapp-payment"] = 100;
        actionPoints["product-purchase"] = 10;
        actionPoints["article-creation"] = 20;
        actionPoints["listing"] = 15;
        actionPoints["quiz-completion"] = 25;
        actionPoints["dao-vote"] = 3;
        actionPoints["game-entry"] = 10;
        actionPoints["daily_login"] = 1;
    }

    /**
     * @dev Returns tier multiplier in BPS. Tier0=10000, Tier1=10000, Tier2=20000, Tier3=50000, Tier4=100000.
     */
    function _tierMultiplierBps(address user) internal view returns (uint256) {
        if (address(krexToken) == address(0)) return BPS;
        uint256 bal = krexToken.balanceOf(user);
        if (bal < TIER1_MIN) return BPS;   // Tier0: 1x
        if (bal < TIER2_MIN) return BPS;   // Tier1: 1x
        if (bal < TIER3_MIN) return 20000; // Tier2: 2x
        if (bal < TIER4_MIN) return 50000; // Tier3: 5x
        return 100000;                     // Tier4: 10x
    }

    /**
     * @dev Public view for FeeRouter to apply same multiplier to tGRID rewards.
     */
    function getTierMultiplierBps(address user) external view returns (uint256) {
        return _tierMultiplierBps(user);
    }

    /**
     * @dev Award points scaled by payment amount: points = (paymentAmountWei/1e18) * pointsPer1iKAS[actionType] * tierBps/BPS. Only callable by authorized (e.g. FeeRouter).
     */
    function awardPointsForPayment(address user, string memory actionType, uint256 paymentAmountWei) external onlyAuthorized {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        if (paymentAmountWei == 0) return;
        uint256 perUnit = pointsPer1iKAS[actionType];
        if (perUnit == 0) return;
        uint256 multBps = _tierMultiplierBps(user);
        uint256 points = (paymentAmountWei * perUnit * multBps) / (1e18 * BPS);
        if (points == 0) points = 1;

        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;

        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) {
                loyalty.streakDays++;
            } else {
                loyalty.streakDays = 1;
            }
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }

        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    /**
     * @dev Award points with on-chain KREX tier multiplier. Only callable by authorized (e.g. FeeRouter).
     */
    function awardPointsWithMultiplier(address user, string memory actionType) external onlyAuthorized {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        uint256 basePoints = actionPoints[actionType];
        if (basePoints == 0) return;
        uint256 multBps = _tierMultiplierBps(user);
        uint256 points = (basePoints * multBps) / BPS;
        if (points == 0) points = 1;

        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;

        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) {
                loyalty.streakDays++;
            } else {
                loyalty.streakDays = 1;
            }
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }

        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    /**
     * @dev Legacy: award base points only. Restricted to owner.
     */
    function awardPoints(address user, string memory actionType) external onlyOwner {
        require(user != address(0), "LoyaltyPoints: Invalid user");
        uint256 points = actionPoints[actionType];
        if (points == 0) return;
        LoyaltyData storage loyalty = userLoyalty[user];
        uint256 prevActivity = loyalty.lastActivity;
        loyalty.totalPoints += points;
        loyalty.lastActivity = block.timestamp;
        if (prevActivity > 0 && (block.timestamp - prevActivity) >= streakInterval) {
            loyalty.participationDays++;
            if ((block.timestamp - prevActivity) < 2 * streakInterval) loyalty.streakDays++;
            else loyalty.streakDays = 1;
            emit StreakUpdated(user, loyalty.streakDays, block.timestamp);
        }
        emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
    }

    function awardPointsBatch(address[] memory users, string[] memory actionTypes) external onlyOwner {
        require(users.length == actionTypes.length, "LoyaltyPoints: Array length mismatch");
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            string memory actionType = actionTypes[i];
            if (user == address(0)) continue;
            uint256 points = actionPoints[actionType];
            if (points == 0) continue;
            LoyaltyData storage loyalty = userLoyalty[user];
            loyalty.totalPoints += points;
            loyalty.lastActivity = block.timestamp;
            emit PointsAwarded(user, actionType, points, loyalty.totalPoints, block.timestamp);
        }
    }

    function getUserLoyalty(address user) external view returns (LoyaltyData memory) {
        return userLoyalty[user];
    }

    function getTotalPoints(address user) external view returns (uint256) {
        return userLoyalty[user].totalPoints;
    }

    function getStreak(address user) external view returns (uint256) {
        return userLoyalty[user].streakDays;
    }

    function setActionPoints(string memory actionType, uint256 points) external onlyOwner {
        uint256 oldPoints = actionPoints[actionType];
        actionPoints[actionType] = points;
        emit ActionPointsUpdated(actionType, oldPoints, points);
    }

    function setPointsPer1iKAS(string memory actionType, uint256 points) external onlyOwner {
        pointsPer1iKAS[actionType] = points;
    }

    function setStreakInterval(uint256 _interval) external onlyOwner {
        streakInterval = _interval;
    }

    function setAuthorizedCaller(address caller, bool allowed) external onlyOwner {
        require(caller != address(0), "LoyaltyPoints: Invalid caller");
        authorizedCallers[caller] = allowed;
        emit AuthorizedCallerSet(caller, allowed);
    }

    function setKREXToken(address _krexToken) external onlyOwner {
        krexToken = IERC20(_krexToken);
        emit KREXTokenSet(_krexToken);
    }
}

contracts/PlatformSubscription.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./Treasury.sol";

/**
 * @title PlatformSubscription
 * @dev Platform-wide subscription contract for fixed monthly KAS payments
 * @notice Users pay a fixed monthly fee set by Kasparex to access all premium dApps
 */
contract PlatformSubscription is Ownable, ReentrancyGuard {
    // Treasury contract for fee collection
    Treasury public treasury;

    // Fixed monthly subscription price (in wei)
    uint256 public monthlyPrice;

    // Subscription period in seconds (default: 30 days)
    uint256 public subscriptionPeriod;

    // Grace period in seconds (default: 7 days)
    uint256 public gracePeriod;

    // Kasparex fee percentage (basis points, e.g., 1500 = 15%)
    uint256 public kasparexFeePercentage;

    // Subscription info for each user
    struct Subscription {
        uint256 expiryTimestamp; // When subscription expires (0 = never subscribed)
        bool isActive; // Whether subscription is currently active
    }

    // Mapping from user address to subscription
    mapping(address => Subscription) public subscriptions;

    // Events
    event SubscriptionPurchased(
        address indexed user,
        uint256 amount,
        uint256 expiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionRenewed(
        address indexed user,
        uint256 amount,
        uint256 newExpiryTimestamp,
        uint256 timestamp
    );
    event SubscriptionExpired(address indexed user, uint256 timestamp);
    event MonthlyPriceUpdated(uint256 oldPrice, uint256 newPrice);
    event SubscriptionPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event GracePeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    /**
     * @dev Constructor sets initial values
     * @param _treasury Address of the Treasury contract
     * @param _monthlyPrice Monthly subscription price in wei
     * @param _subscriptionPeriod Subscription period in seconds (default: 30 days)
     * @param _gracePeriod Grace period in seconds (default: 7 days)
     * @param _kasparexFeePercentage Kasparex fee percentage in basis points (default: 1500 = 15%)
     */
    constructor(
        address _treasury,
        uint256 _monthlyPrice,
        uint256 _subscriptionPeriod,
        uint256 _gracePeriod,
        uint256 _kasparexFeePercentage
    ) Ownable(msg.sender) {
        require(_treasury != address(0), "PlatformSubscription: Invalid treasury address");
        require(_monthlyPrice > 0, "PlatformSubscription: Price must be greater than 0");
        require(_kasparexFeePercentage <= 10000, "PlatformSubscription: Fee cannot exceed 100%");

        treasury = Treasury(_treasury);
        monthlyPrice = _monthlyPrice;
        subscriptionPeriod = _subscriptionPeriod;
        gracePeriod = _gracePeriod;
        kasparexFeePercentage = _kasparexFeePercentage;
    }

    /**
     * @dev Purchase or renew a platform subscription
     * @notice Users pay the fixed monthly price to access all premium dApps
     */
    function subscribe() external payable nonReentrant {
        require(msg.value >= monthlyPrice, "PlatformSubscription: Insufficient payment");

        uint256 kasparexFee = (msg.value * kasparexFeePercentage) / 10000;

        // Send Kasparex fee to treasury
        if (kasparexFee > 0) {
            treasury.collectFee{value: kasparexFee}();
        }

        // Calculate new expiry timestamp
        uint256 currentExpiry = subscriptions[msg.sender].expiryTimestamp;
        uint256 newExpiry;

        if (currentExpiry > block.timestamp) {
            // Renew existing active subscription
            newExpiry = currentExpiry + subscriptionPeriod;
            emit SubscriptionRenewed(msg.sender, msg.value, newExpiry, block.timestamp);
        } else {
            // New subscription
            newExpiry = block.timestamp + subscriptionPeriod;
            emit SubscriptionPurchased(msg.sender, msg.value, newExpiry, block.timestamp);
        }

        subscriptions[msg.sender] = Subscription({
            expiryTimestamp: newExpiry,
            isActive: true
        });

        // Refund excess payment
        if (msg.value > monthlyPrice) {
            uint256 refund = msg.value - monthlyPrice;
            (bool success, ) = payable(msg.sender).call{value: refund}("");
            require(success, "PlatformSubscription: Refund failed");
        }
    }

    /**
     * @dev Check if a user has an active subscription
     * @param _user Address to check
     * @return bool True if subscription is active
     */
    function isSubscribed(address _user) external view returns (bool) {
        Subscription memory sub = subscriptions[_user];
        if (!sub.isActive) return false;
        
        // Check if subscription has expired (including grace period)
        if (sub.expiryTimestamp > 0 && block.timestamp > sub.expiryTimestamp + gracePeriod) {
            return false;
        }
        
        return block.timestamp <= sub.expiryTimestamp;
    }

    /**
     * @dev Check if a user is in grace period
     * @param _user Address to check
     * @return bool True if in grace period
     */
    function isInGracePeriod(address _user) external view returns (bool) {
        Subscription memory sub = subscriptions[_user];
        if (!sub.isActive || sub.expiryTimestamp == 0) return false;
        
        return block.timestamp > sub.expiryTimestamp && 
               block.timestamp <= sub.expiryTimestamp + gracePeriod;
    }

    /**
     * @dev Get subscription expiry timestamp for a user
     * @param _user Address to check
     * @return uint256 Expiry timestamp (0 if not subscribed)
     */
    function getExpiryTimestamp(address _user) external view returns (uint256) {
        return subscriptions[_user].expiryTimestamp;
    }

    /**
     * @dev Update monthly subscription price (only owner)
     * @param _newPrice New monthly price in wei
     */
    function setMonthlyPrice(uint256 _newPrice) external onlyOwner {
        require(_newPrice > 0, "PlatformSubscription: Price must be greater than 0");
        uint256 oldPrice = monthlyPrice;
        monthlyPrice = _newPrice;
        emit MonthlyPriceUpdated(oldPrice, _newPrice);
    }

    /**
     * @dev Update subscription period (only owner)
     * @param _newPeriod New subscription period in seconds
     */
    function setSubscriptionPeriod(uint256 _newPeriod) external onlyOwner {
        require(_newPeriod > 0, "PlatformSubscription: Period must be greater than 0");
        uint256 oldPeriod = subscriptionPeriod;
        subscriptionPeriod = _newPeriod;
        emit SubscriptionPeriodUpdated(oldPeriod, _newPeriod);
    }

    /**
     * @dev Update grace period (only owner)
     * @param _newPeriod New grace period in seconds
     */
    function setGracePeriod(uint256 _newPeriod) external onlyOwner {
        uint256 oldPeriod = gracePeriod;
        gracePeriod = _newPeriod;
        emit GracePeriodUpdated(oldPeriod, _newPeriod);
    }

    /**
     * @dev Update Kasparex fee percentage (only owner)
     * @param _newPercentage New fee percentage in basis points
     */
    function setKasparexFeePercentage(uint256 _newPercentage) external onlyOwner {
        require(_newPercentage <= 10000, "PlatformSubscription: Fee cannot exceed 100%");
        kasparexFeePercentage = _newPercentage;
    }

    /**
     * @dev Update Treasury contract address (only owner)
     * @param _treasury New Treasury contract address
     */
    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "PlatformSubscription: Invalid treasury address");
        address oldTreasury = address(treasury);
        treasury = Treasury(_treasury);
        emit TreasuryUpdated(oldTreasury, _treasury);
    }

    /**
     * @dev Deactivate a subscription (admin function for expired subscriptions)
     * @param _user Address to deactivate
     */
    function deactivateSubscription(address _user) external onlyOwner {
        if (subscriptions[_user].isActive) {
            subscriptions[_user].isActive = false;
            emit SubscriptionExpired(_user, block.timestamp);
        }
    }

    /**
     * @dev Get contract balance
     * @return uint256 Current balance
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Withdraw funds to treasury (only owner)
     * @param _amount Amount to withdraw
     */
    function withdrawToTreasury(uint256 _amount) external onlyOwner nonReentrant {
        require(_amount <= address(this).balance, "PlatformSubscription: Insufficient balance");
        treasury.collectFee{value: _amount}();
    }
}

contracts/ProfileRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ProfileRegistry
 * @dev On-chain profile storage (IPFS CIDs)
 * @notice Maps wallet address to IPFS CID, minimal on-chain storage
 */
contract ProfileRegistry is Ownable {
    // Profile structure
    struct Profile {
        string ipfsCID; // IPFS CID for profile metadata
        string displayName; // Optional on-chain display name
        bool verified; // Verified status
        bytes preferences; // Encoded preferences
        uint256 updatedAt; // Last update timestamp
    }
    
    // User profiles
    mapping(address => Profile) public profiles;
    
    // Verified addresses (for badge display)
    mapping(address => bool) public verifiedAddresses;
    
    // Events
    event ProfileUpdated(address indexed user, string ipfsCID, uint256 timestamp);
    event DisplayNameUpdated(address indexed user, string displayName, uint256 timestamp);
    event VerificationUpdated(address indexed user, bool verified, uint256 timestamp);
    event PreferencesUpdated(address indexed user, bytes preferences, uint256 timestamp);
    
    /**
     * @dev Constructor
     */
    constructor() Ownable(msg.sender) {}
    
    /**
     * @dev Set profile IPFS CID
     * @param user User address
     * @param ipfsCID IPFS CID for profile metadata
     */
    function setProfileCID(address user, string memory ipfsCID) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(bytes(ipfsCID).length > 0, "ProfileRegistry: Invalid IPFS CID");
        
        // Only user or owner can update
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].ipfsCID = ipfsCID;
        profiles[user].updatedAt = block.timestamp;
        
        emit ProfileUpdated(user, ipfsCID, block.timestamp);
    }
    
    /**
     * @dev Set display name (optional on-chain field)
     * @param user User address
     * @param displayName Display name
     */
    function setDisplayName(address user, string memory displayName) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].displayName = displayName;
        emit DisplayNameUpdated(user, displayName, block.timestamp);
    }
    
    /**
     * @dev Set verified status (only owner)
     * @param user User address
     * @param verified Verified status
     */
    function setVerified(address user, bool verified) external onlyOwner {
        require(user != address(0), "ProfileRegistry: Invalid user");
        
        profiles[user].verified = verified;
        verifiedAddresses[user] = verified;
        
        emit VerificationUpdated(user, verified, block.timestamp);
    }
    
    /**
     * @dev Set preferences
     * @param user User address
     * @param preferences Encoded preferences
     */
    function setPreferences(address user, bytes memory preferences) external {
        require(user != address(0), "ProfileRegistry: Invalid user");
        require(msg.sender == user || msg.sender == owner(), "ProfileRegistry: Not authorized");
        
        profiles[user].preferences = preferences;
        emit PreferencesUpdated(user, preferences, block.timestamp);
    }
    
    /**
     * @dev Get profile
     * @param user User address
     * @return Profile struct
     */
    function getProfile(address user) external view returns (Profile memory) {
        return profiles[user];
    }
    
    /**
     * @dev Get profile IPFS CID
     * @param user User address
     * @return IPFS CID
     */
    function getProfileCID(address user) external view returns (string memory) {
        return profiles[user].ipfsCID;
    }
    
    /**
     * @dev Batch update profiles (only owner, gas optimization)
     * @param users Array of user addresses
     * @param ipfsCIDs Array of IPFS CIDs
     */
    function batchUpdateProfiles(address[] memory users, string[] memory ipfsCIDs) external onlyOwner {
        require(users.length == ipfsCIDs.length, "ProfileRegistry: Array length mismatch");
        
        for (uint256 i = 0; i < users.length; i++) {
            if (users[i] != address(0) && bytes(ipfsCIDs[i]).length > 0) {
                profiles[users[i]].ipfsCID = ipfsCIDs[i];
                profiles[users[i]].updatedAt = block.timestamp;
                emit ProfileUpdated(users[i], ipfsCIDs[i], block.timestamp);
            }
        }
    }
}

contracts/ProofOfUtility.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DAppToken.sol";
import "./GRIDToken.sol";
import "./RewardManager.sol";

/**
 * @title ProofOfUtility
 * @dev Tracks on-chain usage events and mints rewards
 * @notice Gas-efficient P-o-U tracking with batch processing
 */
contract ProofOfUtility is Ownable, ReentrancyGuard {
    // RewardManager contract
    RewardManager public rewardManager;
    
    // Usage event structure
    struct UsageEvent {
        address user;
        address dAppContract;
        uint256 dAppId;
        string actionType; // e.g., "vote", "proposal", "payment"
        uint256 timestamp;
    }
    
    // Track events per user
    mapping(address => UsageEvent[]) public userEvents;
    
    // Track events per dApp
    mapping(address => UsageEvent[]) public dAppEvents;
    
    // Event counter
    uint256 public totalEvents;
    
    // Events
    event UsageEventRecorded(
        address indexed user,
        address indexed dAppContract,
        uint256 indexed dAppId,
        string actionType,
        uint256 timestamp
    );
    event RewardMinted(
        address indexed user,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardManagerUpdated(address indexed oldManager, address indexed newManager);
    
    /**
     * @dev Constructor
     * @param _rewardManager Address of RewardManager contract
     */
    constructor(address _rewardManager) Ownable(msg.sender) {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        rewardManager = RewardManager(_rewardManager);
    }
    
    /**
     * @dev Record a usage event (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     */
    function recordUsage(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
    }
    
    /**
     * @dev Record multiple usage events in batch (gas optimization)
     * @param users Array of user addresses
     * @param dAppContracts Array of dApp contract addresses
     * @param dAppIds Array of dApp IDs
     * @param actionTypes Array of action types
     */
    function recordUsageBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory dAppIds,
        string[] memory actionTypes
    ) external {
        require(
            users.length == dAppContracts.length &&
            dAppContracts.length == dAppIds.length &&
            dAppIds.length == actionTypes.length,
            "ProofOfUtility: Array length mismatch"
        );
        
        for (uint256 i = 0; i < users.length; i++) {
            // Inline recordUsage logic for gas efficiency
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 dAppId = dAppIds[i];
            string memory actionType = actionTypes[i];
            
            require(user != address(0), "ProofOfUtility: Invalid user");
            require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
            
            UsageEvent memory event_ = UsageEvent({
                user: user,
                dAppContract: dAppContract,
                dAppId: dAppId,
                actionType: actionType,
                timestamp: block.timestamp
            });
            
            userEvents[user].push(event_);
            dAppEvents[dAppContract].push(event_);
            totalEvents++;
            
            emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        }
    }
    
    /**
     * @dev Get user's usage events
     * @param user User address
     * @return Array of usage events
     */
    function getUserEvents(address user) external view returns (UsageEvent[] memory) {
        return userEvents[user];
    }
    
    /**
     * @dev Get dApp's usage events
     * @param dAppContract dApp contract address
     * @return Array of usage events
     */
    function getDAppEvents(address dAppContract) external view returns (UsageEvent[] memory) {
        return dAppEvents[dAppContract];
    }
    
    /**
     * @dev Get user's event count
     * @param user User address
     * @return Event count
     */
    function getUserEventCount(address user) external view returns (uint256) {
        return userEvents[user].length;
    }
    
    /**
     * @dev Record usage and distribute reward (called by dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     * @param actionValue Value of the action (for reward calculation)
     */
    function recordUsageAndReward(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType,
        uint256 actionValue
    ) public {
        require(user != address(0), "ProofOfUtility: Invalid user");
        require(dAppContract != address(0), "ProofOfUtility: Invalid dApp contract");
        
        // Record usage event
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp);
        
        // Distribute reward if actionValue > 0
        if (actionValue > 0) {
            rewardManager.distributeReward(user, dAppContract, actionValue);
        }
    }
    
    /**
     * @dev Update reward manager (only owner)
     * @param _rewardManager New reward manager address
     */
    function setRewardManager(address _rewardManager) external onlyOwner {
        require(_rewardManager != address(0), "ProofOfUtility: Invalid reward manager");
        address oldManager = address(rewardManager);
        rewardManager = RewardManager(_rewardManager);
        emit RewardManagerUpdated(oldManager, _rewardManager);
    }
}

contracts/QuizToEarn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./FeeCollector.sol";
import "./ProofOfUtility.sol";

/**
 * @title QuizToEarn
 * @dev Quiz game where users answer questions to earn rewards
 * @notice Users answer crypto/ecosystem questions and earn GRID or token rewards for correct answers
 */
contract QuizToEarn is Ownable, ReentrancyGuard {
    FeeCollector public feeCollector;
    ProofOfUtility public proofOfUtility;
    uint256 public dAppId; // To be set by DAppRegistry after registration
    
    // Default fee configuration (1% = 100 basis points)
    uint256 public feePercentage = 100; // 1% default fee
    uint256 public constant BASIS_POINTS = 10000; // 100% = 10000 basis points
    
    // Quiz question structure
    struct Question {
        uint256 id;
        string questionText;
        string[] options; // Array of answer options
        uint256 correctAnswerIndex; // Index of correct answer (0-based)
        string category; // e.g., "Kaspa", "BlockDAG", "General"
        uint256 rewardAmount; // Reward amount in wei for correct answer
        bool isActive; // Whether question is active
        uint256 createdAt;
    }
    
    // User answer tracking
    struct UserAnswer {
        uint256 questionId;
        uint256 selectedAnswerIndex;
        bool isCorrect;
        uint256 timestamp;
        bool rewardClaimed;
    }
    
    // State variables
    mapping(uint256 => Question) public questions;
    mapping(address => mapping(uint256 => UserAnswer)) public userAnswers; // user => questionId => answer
    mapping(address => uint256[]) public userAnsweredQuestions; // user => array of question IDs
    uint256 public questionCount;
    uint256 public defaultRewardAmount; // Default reward value per correct answer (used for RewardManager calculation, represents token value, not KAS)
    
    // Events
    event QuestionAdded(
        uint256 indexed questionId,
        string questionText,
        string category,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event QuestionUpdated(uint256 indexed questionId, bool isActive);
    event AnswerSubmitted(
        address indexed user,
        uint256 indexed questionId,
        uint256 selectedAnswerIndex,
        bool isCorrect,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event RewardClaimed(
        address indexed user,
        uint256 indexed questionId,
        uint256 rewardAmount,
        uint256 timestamp
    );
    event DAppInitialized(uint256 indexed dAppId, address indexed deployer, uint256 timestamp);
    event DefaultRewardUpdated(uint256 oldReward, uint256 newReward);
    
    /**
     * @dev Constructor
     * @param _feeCollector Address of the FeeCollector contract
     * @param _proofOfUtility Address of the ProofOfUtility contract
     * @param _feePercentage Initial fee percentage in basis points (default: 100 = 1%)
     * @param _defaultRewardAmount Default reward value per correct answer (used for RewardManager calculation, represents token value, not KAS)
     */
    constructor(
        address _feeCollector,
        address _proofOfUtility,
        uint256 _feePercentage,
        uint256 _defaultRewardAmount
    ) Ownable(msg.sender) {
        require(_feeCollector != address(0), "QuizToEarn: Invalid fee collector");
        require(_proofOfUtility != address(0), "QuizToEarn: Invalid ProofOfUtility");
        require(_feePercentage <= BASIS_POINTS, "QuizToEarn: Fee percentage too high");
        
        feeCollector = FeeCollector(_feeCollector);
        proofOfUtility = ProofOfUtility(_proofOfUtility);
        feePercentage = _feePercentage == 0 ? 100 : _feePercentage; // Default to 1% if not provided
        defaultRewardAmount = _defaultRewardAmount;
    }
    
    /**
     * @dev Sets the dApp ID after registration in the DAppRegistry.
     *      This function can only be called once by the owner.
     * @param _dAppId The ID assigned by the DAppRegistry.
     */
    function setDAppId(uint256 _dAppId) external onlyOwner {
        require(dAppId == 0, "QuizToEarn: dApp ID already set");
        require(_dAppId > 0, "QuizToEarn: Invalid dApp ID");
        dAppId = _dAppId;
        emit DAppInitialized(dAppId, msg.sender, block.timestamp);
    }
    
    /**
     * @dev Add a new quiz question (admin only)
     * @param _questionText The question text
     * @param _options Array of answer options
     * @param _correctAnswerIndex Index of the correct answer (0-based)
     * @param _category Category of the question (e.g., "Kaspa", "BlockDAG")
     * @param _rewardAmount Reward value for correct answer (used for RewardManager calculation, represents token value, not KAS. 0 = use default)
     */
    function addQuestion(
        string memory _questionText,
        string[] memory _options,
        uint256 _correctAnswerIndex,
        string memory _category,
        uint256 _rewardAmount
    ) external onlyOwner {
        require(bytes(_questionText).length > 0, "QuizToEarn: Question text cannot be empty");
        require(_options.length >= 2, "QuizToEarn: Must have at least 2 options");
        require(_correctAnswerIndex < _options.length, "QuizToEarn: Invalid correct answer index");
        
        questionCount++;
        uint256 rewardAmount = _rewardAmount == 0 ? defaultRewardAmount : _rewardAmount;
        
        questions[questionCount] = Question({
            id: questionCount,
            questionText: _questionText,
            options: _options,
            correctAnswerIndex: _correctAnswerIndex,
            category: _category,
            rewardAmount: rewardAmount,
            isActive: true,
            createdAt: block.timestamp
        });
        
        emit QuestionAdded(questionCount, _questionText, _category, rewardAmount, block.timestamp);
    }
    
    /**
     * @dev Update question active status (admin only)
     * @param _questionId Question ID
     * @param _isActive Whether question is active
     */
    function updateQuestionStatus(uint256 _questionId, bool _isActive) external onlyOwner {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        questions[_questionId].isActive = _isActive;
        emit QuestionUpdated(_questionId, _isActive);
    }
    
    /**
     * @dev Submit an answer to a question
     * @param _questionId Question ID
     * @param _selectedAnswerIndex Selected answer index (0-based)
     */
    function submitAnswer(uint256 _questionId, uint256 _selectedAnswerIndex) external nonReentrant {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        Question storage question = questions[_questionId];
        require(question.isActive, "QuizToEarn: Question is not active");
        require(_selectedAnswerIndex < question.options.length, "QuizToEarn: Invalid answer index");
        require(
            userAnswers[msg.sender][_questionId].timestamp == 0,
            "QuizToEarn: Question already answered"
        );
        
        bool isCorrect = _selectedAnswerIndex == question.correctAnswerIndex;
        
        userAnswers[msg.sender][_questionId] = UserAnswer({
            questionId: _questionId,
            selectedAnswerIndex: _selectedAnswerIndex,
            isCorrect: isCorrect,
            timestamp: block.timestamp,
            rewardClaimed: false
        });
        
        userAnsweredQuestions[msg.sender].push(_questionId);
        
        // Record usage event and distribute reward via ProofOfUtility
        // Only distribute rewards for correct answers
        if (dAppId > 0 && isCorrect) {
            // Use rewardAmount as actionValue (represents value in token terms, not KAS)
            // RewardManager will calculate actual token reward: actionValue × rewardRate
            proofOfUtility.recordUsageAndReward(
                msg.sender,
                address(this),
                dAppId,
                "quiz_correct_answer",
                question.rewardAmount // This represents the value, RewardManager calculates token amount
            );
        } else if (dAppId > 0) {
            // Record wrong answer without reward
            proofOfUtility.recordUsage(
                msg.sender,
                address(this),
                dAppId,
                "quiz_wrong_answer"
            );
        }
        
        emit AnswerSubmitted(
            msg.sender,
            _questionId,
            _selectedAnswerIndex,
            isCorrect,
            isCorrect ? question.rewardAmount : 0,
            block.timestamp
        );
    }
    
    /**
     * @dev Get a question by ID
     * @param _questionId Question ID
     * @return id Question ID
     * @return questionText Question text
     * @return options Array of answer options
     * @return category Question category
     * @return rewardAmount Reward amount for correct answer
     * @return isActive Whether question is active
     * @return createdAt Creation timestamp
     */
    function getQuestion(uint256 _questionId) external view returns (
        uint256 id,
        string memory questionText,
        string[] memory options,
        string memory category,
        uint256 rewardAmount,
        bool isActive,
        uint256 createdAt
    ) {
        require(_questionId > 0 && _questionId <= questionCount, "QuizToEarn: Invalid question ID");
        Question storage q = questions[_questionId];
        return (
            q.id,
            q.questionText,
            q.options,
            q.category,
            q.rewardAmount,
            q.isActive,
            q.createdAt
        );
    }
    
    /**
     * @dev Get user's answer for a question
     * @param _user User address
     * @param _questionId Question ID
     * @return UserAnswer struct
     */
    function getUserAnswer(address _user, uint256 _questionId) external view returns (UserAnswer memory) {
        return userAnswers[_user][_questionId];
    }
    
    /**
     * @dev Get all question IDs answered by a user
     * @param _user User address
     * @return Array of question IDs
     */
    function getUserAnsweredQuestions(address _user) external view returns (uint256[] memory) {
        return userAnsweredQuestions[_user];
    }
    
    /**
     * @dev Get paginated active questions
     * @param _offset Starting index
     * @param _limit Number of questions to return
     * @return ids Array of question IDs
     * @return questionTexts Array of question texts
     * @return optionsArray Array of options arrays
     * @return categories Array of categories
     * @return rewardAmounts Array of reward amounts
     */
    function getActiveQuestions(uint256 _offset, uint256 _limit) external view returns (
        uint256[] memory ids,
        string[] memory questionTexts,
        string[][] memory optionsArray,
        string[] memory categories,
        uint256[] memory rewardAmounts
    ) {
        require(_limit > 0 && _limit <= 50, "QuizToEarn: Invalid limit");
        
        uint256 count = 0;
        uint256[] memory tempIds = new uint256[](_limit);
        string[] memory tempTexts = new string[](_limit);
        string[][] memory tempOptions = new string[][](_limit);
        string[] memory tempCategories = new string[](_limit);
        uint256[] memory tempRewards = new uint256[](_limit);
        
        for (uint256 i = _offset + 1; i <= questionCount && count < _limit; i++) {
            if (questions[i].isActive) {
                tempIds[count] = questions[i].id;
                tempTexts[count] = questions[i].questionText;
                tempOptions[count] = questions[i].options;
                tempCategories[count] = questions[i].category;
                tempRewards[count] = questions[i].rewardAmount;
                count++;
            }
        }
        
        // Resize arrays to actual count
        uint256[] memory finalIds = new uint256[](count);
        string[] memory finalTexts = new string[](count);
        string[][] memory finalOptions = new string[][](count);
        string[] memory finalCategories = new string[](count);
        uint256[] memory finalRewards = new uint256[](count);
        
        for (uint256 i = 0; i < count; i++) {
            finalIds[i] = tempIds[i];
            finalTexts[i] = tempTexts[i];
            finalOptions[i] = tempOptions[i];
            finalCategories[i] = tempCategories[i];
            finalRewards[i] = tempRewards[i];
        }
        
        return (finalIds, finalTexts, finalOptions, finalCategories, finalRewards);
    }
    
    /**
     * @dev Update default reward amount (admin only)
     * @param _newRewardAmount New default reward value (used for RewardManager calculation, represents token value, not KAS)
     */
    function setDefaultRewardAmount(uint256 _newRewardAmount) external onlyOwner {
        uint256 oldReward = defaultRewardAmount;
        defaultRewardAmount = _newRewardAmount;
        emit DefaultRewardUpdated(oldReward, _newRewardAmount);
    }
    
    /**
     * @dev Admin function - Update fee percentage (admin only)
     * @param _newFeePercentage New fee percentage in basis points (e.g., 100 = 1%)
     */
    function setFeePercentage(uint256 _newFeePercentage) external onlyOwner {
        require(_newFeePercentage <= BASIS_POINTS, "QuizToEarn: Fee percentage too high");
        feePercentage = _newFeePercentage;
    }
    
    /**
     * @dev Calculate fee for a given amount
     * @param _amount Amount to calculate fee for
     * @return Fee amount in wei
     */
    function calculateFee(uint256 _amount) public view returns (uint256) {
        return (_amount * feePercentage) / BASIS_POINTS;
    }
    
    /**
     * @dev Admin function - Update fee collector (admin only)
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "QuizToEarn: Invalid fee collector");
        feeCollector = FeeCollector(_feeCollector);
    }
    
    /**
     * @dev Admin function - Update ProofOfUtility (admin only)
     * @param _proofOfUtility New ProofOfUtility address
     */
    function setProofOfUtility(address _proofOfUtility) external onlyOwner {
        require(_proofOfUtility != address(0), "QuizToEarn: Invalid ProofOfUtility");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
    }
}

contracts/RevenueTreeManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title RevenueTreeManager
 * @dev Unified Revenue Tree per wallet per chain: referrer, volume, activation, upline snapshot, revenue distribution.
 * @notice One tree per wallet; upline immutable at activation; revenue to upline or matched Genesis when inactive.
 * Version 5 Design: Pull payment for platform, tiered activity maintenance, Push-Up Rule activation, anti-spam.
 */
contract RevenueTreeManager is Ownable, ReentrancyGuard {
    // --- Constants ---
    uint256 public constant BPS = 10000;
    uint256 public constant SECONDS_PER_DAY = 86400;
    uint256 public constant WINDOW_DAYS = 30;
    uint256 public constant MAX_CYCLE_DEPTH = 10;

    // --- Core Config ---
    uint256 public numLevels;
    address[] public genesisWallets;
    
    uint256[] public levelBps;
    uint256 public platformBps;
    address public platformWallet;

    // --- Thresholds & Multipliers ---
    uint256 public activationThreshold;   // lifetime volume to activate (native wei)
    uint256 public baseActivityThreshold; // base rolling 30-day volume to stay active (e.g. 100 KAS)
    uint256 public minVolumePerCall;      // minimum tx value to count toward activity (anti-spam)
    uint256 public krexMinVolumeFloor;    // floor volume required even with max KREX discount

    uint256[] public levelVolumeMultipliers; // e.g. [1, 2, 5, 10, 20]
    
    IERC20 public krexToken; // address(0) = disabled
    uint256[] public krexTiersHoldings;  // e.g. [1000e18, 5000e18, 10000e18, 50000e18]
    uint256[] public krexTiersDiscounts; // in BPS. e.g. [2500, 5000, 7500, 9000]

    // --- State ---
    mapping(address => bool) public authorizedCallers;
    mapping(address => address) public referrerOf;
    mapping(address => uint256) public lifetimeVolume;
    mapping(address => uint256) public activatedAt;           // 0 = not activated
    mapping(address => address[]) public upline;              // frozen snapshot at activation
    mapping(address => mapping(uint256 => uint256)) public volumeByDay; // [user][dayIndex] -> volume
    
    mapping(address => uint256) public totalReceived;         // on-chain earnings accumulator
    mapping(address => uint256) public pendingWithdrawals;    // pull payment system for platform

    // --- Events ---
    event ReferrerSet(address indexed user, address indexed referrer);
    event Activated(address indexed user, address[] uplineSnapshot);
    event RevenueDistributed(address indexed payer, uint256 amount, uint256 level, address indexed recipient, bool isGenesis);
    event PlatformFeePending(address indexed platform, uint256 amount);
    event Withdrawal(address indexed recipient, uint256 amount);
    event AuthorizedCallerSet(address indexed caller, bool allowed);
    event ConfigUpdated();

    error InvalidAddress();
    error Unauthorized();
    error ReferrerAlreadySet();
    error TransferFailed();
    error CycleDetected();
    error InvalidConfiguration();

    modifier onlyAuthorized() {
        if (!authorizedCallers[msg.sender]) revert Unauthorized();
        _;
    }

    /**
     * @param _genesisWallets Genesis addresses
     * @param _platformWallet Receives platform share remainder
     * @param _krexToken KREX token or address(0)
     * @param _activationThreshold Lifetime volume to activate (wei)
     * @param _baseActivityThreshold Base volume in last 30 days for activity
     * @param _minVolumePerCall Anti-spam volume floor per transaction
     * @param _krexMinVolumeFloor Absolute minimum volume required with max KREX discount
     */
    constructor(
        address[] memory _genesisWallets,
        address _platformWallet,
        address _krexToken,
        uint256 _activationThreshold,
        uint256 _baseActivityThreshold,
        uint256 _minVolumePerCall,
        uint256 _krexMinVolumeFloor
    ) Ownable(msg.sender) {
        if (_platformWallet == address(0)) revert InvalidAddress();

        numLevels = 5;
        if (_genesisWallets.length < numLevels) revert InvalidConfiguration();
        genesisWallets = _genesisWallets;

        platformWallet = _platformWallet;
        krexToken = IERC20(_krexToken);

        activationThreshold = _activationThreshold;
        baseActivityThreshold = _baseActivityThreshold;
        minVolumePerCall = _minVolumePerCall;
        krexMinVolumeFloor = _krexMinVolumeFloor;

        levelBps = new uint256[](5);
        levelBps[0] = 200; // L1 2%
        levelBps[1] = 500; // L2 5%
        levelBps[2] = 1000; // L3 10%
        levelBps[3] = 2000; // L4 20%
        levelBps[4] = 4500; // L5 45%

        platformBps = 1800; // 18% remainder

        levelVolumeMultipliers = new uint256[](5);
        levelVolumeMultipliers[0] = 1;
        levelVolumeMultipliers[1] = 2;
        levelVolumeMultipliers[2] = 5;
        levelVolumeMultipliers[3] = 10;
        levelVolumeMultipliers[4] = 20;
    }

    /**
     * @dev Set referrer once per user. Prevents circular references.
     */
    function setReferrer(address referrer) external {
        if (referrer == address(0) || referrer == msg.sender) revert InvalidAddress();
        if (referrerOf[msg.sender] != address(0)) revert ReferrerAlreadySet();
        if (_wouldCreateCycle(msg.sender, referrer)) revert CycleDetected();
        
        referrerOf[msg.sender] = referrer;
        emit ReferrerSet(msg.sender, referrer);
    }

    function _wouldCreateCycle(address user, address candidate) internal view returns (bool) {
        address cursor = candidate;
        for (uint256 i = 0; i < MAX_CYCLE_DEPTH; i++) {
            if (cursor == address(0)) return false;
            if (cursor == user) return true;
            cursor = referrerOf[cursor];
        }
        return false;
    }

    /**
     * @dev Distribute msg.value to payer's upline (Push-up). Platform gets pull-payout.
     * @param totalVolume The full transactional value processed (e.g. 10 iKAS), used for tier maintenance. msg.value is only the tree's split (e.g. 5 iKAS).
     */
    function distributeToUpline(address payer, uint256 totalVolume) external payable onlyAuthorized nonReentrant {
        if (payer == address(0) || msg.value == 0) return;

        uint256 dayIndex = block.timestamp / SECONDS_PER_DAY;
        
        // Anti-spam volume rule
        if (totalVolume >= minVolumePerCall) {
            lifetimeVolume[payer] += totalVolume;
            volumeByDay[payer][dayIndex] += totalVolume;
        }

        // Activate if crossing threshold
        if (activatedAt[payer] == 0 && lifetimeVolume[payer] >= activationThreshold) {
            _activate(payer);
        }

        address[] memory recipients = upline[payer];
        uint256 activeLength = activatedAt[payer] == 0 ? 0 : recipients.length;

        uint256 sent = 0;
        for (uint256 i = 0; i < numLevels; i++) {
            uint256 amount = (msg.value * levelBps[i]) / BPS;
            if (amount == 0) continue;

            address to = address(0);
            if (i < activeLength) {
                to = recipients[i];
            }
            
            bool isGenesis = false;
            if (to == address(0) || to == genesisWallets[i] || !_isActive(to, i)) {
                to = genesisWallets[i];
                isGenesis = true;
            }

            totalReceived[to] += amount;
            (bool ok, ) = payable(to).call{value: amount}("");
            if (!ok) revert TransferFailed();
            
            sent += amount;
            emit RevenueDistributed(payer, amount, i + 1, to, isGenesis);
        }

        uint256 platformAmount = msg.value - sent;
        if (platformAmount > 0) {
            pendingWithdrawals[platformWallet] += platformAmount;
            emit PlatformFeePending(platformWallet, platformAmount);
        }
    }

    /**
     * @dev Push-up Rule: inherit referrer's frozen upline shifted by 1. L1 = direct referrer. 
     */
    function _activate(address user) internal {
        address ref = referrerOf[user];
        address[] memory newUpline = new address[](numLevels);
        
        newUpline[0] = ref; // L1 = direct referrer
        
        if (ref != address(0)) {
            address[] memory refUpline = upline[ref];
            for (uint256 i = 1; i < numLevels; i++) {
                if (i - 1 < refUpline.length) {
                    newUpline[i] = refUpline[i - 1];
                } else {
                    newUpline[i] = address(0);
                }
            }
        }
        
        upline[user] = newUpline;
        activatedAt[user] = block.timestamp;
        emit Activated(user, newUpline);
    }

    /**
     * @dev Tiered activity check: user must have volume >= (base * levelMultiplier) - KREX discount
     */
    function _isActive(address user, uint256 level) internal view returns (bool) {
        if (user == address(0)) return false;
        if (level >= levelVolumeMultipliers.length) return false;
        
        uint256 baseReq = baseActivityThreshold * levelVolumeMultipliers[level];
        uint256 discountBps = 0;
        
        if (address(krexToken) != address(0) && krexTiersHoldings.length > 0) {
            uint256 balance = krexToken.balanceOf(user);
            uint256 highestDiscount = 0;
            for (uint256 i = 0; i < krexTiersHoldings.length; i++) {
                if (balance >= krexTiersHoldings[i]) {
                    if (i < krexTiersDiscounts.length && krexTiersDiscounts[i] > highestDiscount) {
                        highestDiscount = krexTiersDiscounts[i];
                    }
                }
            }
            discountBps = highestDiscount;
        }

        uint256 discountAmount = (baseReq * discountBps) / BPS;
        uint256 req = baseReq > discountAmount ? baseReq - discountAmount : 0;
        
        // Floor protection
        if (req < krexMinVolumeFloor) {
            req = krexMinVolumeFloor;
        }

        uint256 vol30 = getVolumeLast30Days(user);
        return vol30 >= req;
    }

    function getVolumeLast30Days(address user) public view returns (uint256) {
        uint256 today = block.timestamp / SECONDS_PER_DAY;
        uint256 sum = 0;
        for (uint256 d = 0; d < WINDOW_DAYS; d++) {
            uint256 day = today - d;
            sum += volumeByDay[user][day];
        }
        return sum;
    }

    function isActiveAtLevel(address user, uint256 level) external view returns (bool) {
        return _isActive(user, level);
    }

    function getUpline(address user) external view returns (address[] memory) {
        if (activatedAt[user] == 0) {
            address[] memory out = new address[](numLevels);
            for (uint256 i = 0; i < numLevels; i++) {
                out[i] = genesisWallets[i];
            }
            return out;
        }
        return upline[user];
    }

    function getActivationStatus(address user) external view returns (bool activated, address[] memory uplineSnapshot) {
        activated = activatedAt[user] != 0;
        if (activated) {
            uplineSnapshot = upline[user];
        } else {
            uplineSnapshot = new address[](numLevels);
            for (uint256 i = 0; i < numLevels; i++) {
                uplineSnapshot[i] = genesisWallets[i];
            }
        }
        return (activated, uplineSnapshot);
    }
    
    // --- Pull Payment Withdraw ---
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert TransferFailed();
        pendingWithdrawals[msg.sender] = 0;
        
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();
        
        emit Withdrawal(msg.sender, amount);
    }

    // --- Admin Functions ---

    function setAuthorizedCaller(address caller, bool allowed) external onlyOwner {
        authorizedCallers[caller] = allowed;
        emit AuthorizedCallerSet(caller, allowed);
    }

    function setGenesisWallets(address[] calldata _genesisWallets) external onlyOwner {
        if (_genesisWallets.length < numLevels) revert InvalidConfiguration();
        genesisWallets = _genesisWallets;
        emit ConfigUpdated();
    }

    function setKrexToken(address _krexToken) external onlyOwner {
        krexToken = IERC20(_krexToken);
        emit ConfigUpdated();
    }

    function setPlatformWallet(address _platformWallet) external onlyOwner {
        if (_platformWallet == address(0)) revert InvalidAddress();
        platformWallet = _platformWallet;
        emit ConfigUpdated();
    }
    
    function setActivationThreshold(uint256 _threshold) external onlyOwner {
        activationThreshold = _threshold;
        emit ConfigUpdated();
    }
    
    function setBaseActivityThreshold(uint256 _threshold) external onlyOwner {
        baseActivityThreshold = _threshold;
        emit ConfigUpdated();
    }
    
    function setMinVolumePerCall(uint256 _minVol) external onlyOwner {
        minVolumePerCall = _minVol;
        emit ConfigUpdated();
    }
    
    function setKrexMinVolumeFloor(uint256 _floor) external onlyOwner {
        krexMinVolumeFloor = _floor;
        emit ConfigUpdated();
    }
    
    function setNumLevels(uint256 _num) external onlyOwner {
        if (_num == 0 || _num > genesisWallets.length) revert InvalidConfiguration();
        numLevels = _num;
        emit ConfigUpdated();
    }
    
    function setLevelBps(uint256[] calldata _bps, uint256 _platformBps) external onlyOwner {
        if (_bps.length != numLevels) revert InvalidConfiguration();
        uint256 sum = 0;
        for (uint256 i = 0; i < _bps.length; i++) {
            sum += _bps[i];
        }
        if (sum + _platformBps != BPS) revert InvalidConfiguration();
        levelBps = _bps;
        platformBps = _platformBps;
        emit ConfigUpdated();
    }
    
    function setLevelVolumeMultipliers(uint256[] calldata _multipliers) external onlyOwner {
        if (_multipliers.length != numLevels) revert InvalidConfiguration();
        levelVolumeMultipliers = _multipliers;
        emit ConfigUpdated();
    }
    
    function setKrexTiers(uint256[] calldata holds, uint256[] calldata discounts) external onlyOwner {
        if (holds.length != discounts.length) revert InvalidConfiguration();
        krexTiersHoldings = holds;
        krexTiersDiscounts = discounts;
        emit ConfigUpdated();
    }

    receive() external payable {}
}

contracts/RewardManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./GRIDToken.sol";
import "./ProofOfUtility.sol";

/**
 * @title RewardManager
 * @dev Distributes GRID only. FeeRouter uses distributeRewardDirect (95% user, 5% treasury).
 * @notice ProofOfUtility path (distributeReward) is deprecated for reward flow; use for analytics only.
 */
contract RewardManager is Ownable, ReentrancyGuard {
    uint256 public constant BPS = 10000;
    uint256 public constant GRID_TREASURY_BPS = 500; // 5%

    ProofOfUtility public proofOfUtility;
    GRIDToken public gridToken;
    address public gridTreasury;
    mapping(address => bool) public authorizedRewardCallers; // e.g. FeeRouter

    mapping(address => uint256) public rewardRates;

    event RewardDistributed(
        address indexed user,
        address indexed dAppContract,
        address indexed token,
        uint256 amount,
        string rewardType
    );
    event RewardDistributedDirect(address indexed user, uint256 amountToUser, uint256 amountToTreasury);
    event RewardRateUpdated(address indexed dAppContract, uint256 oldRate, uint256 newRate);
    event GridTreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event AuthorizedRewardCallerSet(address indexed caller, bool allowed);
    
    modifier onlyAuthorizedRewardCaller() {
        require(authorizedRewardCallers[msg.sender], "RewardManager: Unauthorized");
        _;
    }

    constructor(address _proofOfUtility, address _gridToken) Ownable(msg.sender) {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        require(_gridToken != address(0), "RewardManager: Invalid GRID token");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
        gridToken = GRIDToken(_gridToken);
    }

    /**
     * @dev Direct GRID distribution: 95% to user, 5% to gridTreasury. Callable only by FeeRouter (or authorized).
     */
    function distributeRewardDirect(address user, uint256 amountWei) external nonReentrant onlyAuthorizedRewardCaller {
        require(user != address(0), "RewardManager: Invalid user");
        require(amountWei > 0, "RewardManager: Zero amount");
        require(gridTreasury != address(0), "RewardManager: Treasury not set");
        uint256 toUser = (amountWei * (BPS - GRID_TREASURY_BPS)) / BPS;
        uint256 toTreasury = amountWei - toUser;
        require(gridToken.balanceOf(address(this)) >= amountWei, "RewardManager: Insufficient GRID");
        require(gridToken.transfer(user, toUser), "RewardManager: Transfer to user failed");
        require(gridToken.transfer(gridTreasury, toTreasury), "RewardManager: Transfer to treasury failed");
        emit RewardDistributedDirect(user, toUser, toTreasury);
    }

    /**
     * @dev Legacy: distribute GRID for a usage event (ProofOfUtility only). Prefer FeeRouter -> distributeRewardDirect.
     */
    function distributeReward(
        address user,
        address dAppContract,
        uint256 actionValue
    ) public nonReentrant {
        require(user != address(0), "RewardManager: Invalid user");
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        uint256 rewardRate = rewardRates[dAppContract];
        if (rewardRate == 0) return;
        uint256 rewardAmount = (actionValue * rewardRate) / 10000;
        if (rewardAmount == 0) return;
        require(gridToken.balanceOf(address(this)) >= rewardAmount, "RewardManager: Insufficient GRID");
        require(gridToken.transfer(user, rewardAmount), "RewardManager: GRID transfer failed");
        emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
    }

    /**
     * @dev Batch distribute GRID (ProofOfUtility only).
     */
    function distributeRewardsBatch(
        address[] memory users,
        address[] memory dAppContracts,
        uint256[] memory actionValues
    ) external nonReentrant {
        require(
            users.length == dAppContracts.length && dAppContracts.length == actionValues.length,
            "RewardManager: Array length mismatch"
        );
        require(msg.sender == address(proofOfUtility), "RewardManager: Only ProofOfUtility can call");
        for (uint256 i = 0; i < users.length; i++) {
            address user = users[i];
            address dAppContract = dAppContracts[i];
            uint256 actionValue = actionValues[i];
            if (user == address(0) || dAppContract == address(0)) continue;
            uint256 rewardRate = rewardRates[dAppContract];
            if (rewardRate == 0) continue;
            uint256 rewardAmount = (actionValue * rewardRate) / 10000;
            if (rewardAmount == 0) continue;
            if (gridToken.balanceOf(address(this)) < rewardAmount) continue;
            if (!gridToken.transfer(user, rewardAmount)) continue;
            emit RewardDistributed(user, dAppContract, address(gridToken), rewardAmount, "GRID");
        }
    }

    function setRewardRate(address dAppContract, uint256 rate) external onlyOwner {
        require(dAppContract != address(0), "RewardManager: Invalid dApp contract");
        require(rate <= 10000, "RewardManager: Rate cannot exceed 100%");
        uint256 oldRate = rewardRates[dAppContract];
        rewardRates[dAppContract] = rate;
        emit RewardRateUpdated(dAppContract, oldRate, rate);
    }

    function setGridTreasury(address _gridTreasury) external onlyOwner {
        require(_gridTreasury != address(0), "RewardManager: Invalid treasury");
        address old = gridTreasury;
        gridTreasury = _gridTreasury;
        emit GridTreasuryUpdated(old, _gridTreasury);
    }

    function setAuthorizedRewardCaller(address caller, bool allowed) external onlyOwner {
        require(caller != address(0), "RewardManager: Invalid caller");
        authorizedRewardCallers[caller] = allowed;
        emit AuthorizedRewardCallerSet(caller, allowed);
    }

    function setProofOfUtility(address _proofOfUtility) external onlyOwner {
        require(_proofOfUtility != address(0), "RewardManager: Invalid ProofOfUtility");
        proofOfUtility = ProofOfUtility(_proofOfUtility);
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title RewardVault
 * @dev Holds pre-minted GRID and dApp tokens for distribution
 * @notice Manages token reserves for RewardManager
 */
contract RewardVault is Ownable, ReentrancyGuard {
    // RewardManager contract
    address public rewardManager;
    
    // Token balances
    mapping(address => uint256) public tokenBalances; // token -> balance
    
    // Events
    event TokensDeposited(address indexed token, uint256 amount, uint256 timestamp);
    event TokensWithdrawn(address indexed token, address indexed to, uint256 amount, uint256 timestamp);
    event RewardManagerUpdated(address indexed oldManager, address indexed newManager);
    
    /**
     * @dev Constructor
     * @param _rewardManager RewardManager contract address
     */
    constructor(address _rewardManager) Ownable(msg.sender) {
        require(_rewardManager != address(0), "RewardVault: Invalid reward manager");
        rewardManager = _rewardManager;
    }
    
    /**
     * @dev Deposit tokens to vault
     * @param token Token address
     * @param amount Amount to deposit
     */
    function deposit(address token, uint256 amount) external nonReentrant {
        require(token != address(0), "RewardVault: Invalid token");
        require(amount > 0, "RewardVault: Invalid amount");
        
        IERC20 tokenContract = IERC20(token);
        require(
            tokenContract.transferFrom(msg.sender, address(this), amount),
            "RewardVault: Transfer failed"
        );
        
        tokenBalances[token] += amount;
        emit TokensDeposited(token, amount, block.timestamp);
    }
    
    /**
     * @dev Withdraw tokens from vault (only RewardManager)
     * @param token Token address
     * @param to Recipient address
     * @param amount Amount to withdraw
     */
    function withdraw(address token, address to, uint256 amount) external nonReentrant {
        require(msg.sender == rewardManager, "RewardVault: Only RewardManager can withdraw");
        require(token != address(0), "RewardVault: Invalid token");
        require(to != address(0), "RewardVault: Invalid recipient");
        require(amount > 0, "RewardVault: Invalid amount");
        require(tokenBalances[token] >= amount, "RewardVault: Insufficient balance");
        
        tokenBalances[token] -= amount;
        
        IERC20 tokenContract = IERC20(token);
        require(
            tokenContract.transfer(to, amount),
            "RewardVault: Transfer failed"
        );
        
        emit TokensWithdrawn(token, to, amount, block.timestamp);
    }
    
    /**
     * @dev Get token balance
     * @param token Token address
     * @return Balance
     */
    function getBalance(address token) external view returns (uint256) {
        return tokenBalances[token];
    }
    
    /**
     * @dev Update RewardManager (only owner)
     * @param _rewardManager New RewardManager address
     */
    function setRewardManager(address _rewardManager) external onlyOwner {
        require(_rewardManager != address(0), "RewardVault: Invalid reward manager");
        address oldManager = rewardManager;
        rewardManager = _rewardManager;
        emit RewardManagerUpdated(oldManager, _rewardManager);
    }
    
    /**
     * @dev Emergency withdraw (only owner)
     * @param token Token address
     * @param to Recipient address
     * @param amount Amount to withdraw
     */
    function emergencyWithdraw(address token, address to, uint256 amount) external onlyOwner nonReentrant {
        require(token != address(0), "RewardVault: Invalid token");
        require(to != address(0), "RewardVault: Invalid recipient");
        
        IERC20 tokenContract = IERC20(token);
        require(
            tokenContract.transfer(to, amount),
            "RewardVault: Transfer failed"
        );
        
        if (tokenBalances[token] >= amount) {
            tokenBalances[token] -= amount;
        }
    }
}

contracts/SecureProofOfUtility.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./DAppToken.sol";
import "./GRIDToken.sol";
import "./RewardManager.sol";

/**
 * @title SecureProofOfUtility
 * @dev Secure version of ProofOfUtility with access control, action verification, and anti-replay protection
 * @notice Prevents unauthorized reward minting and cross-contract exploitation
 */
contract SecureProofOfUtility is Ownable, ReentrancyGuard, Pausable {
    // RewardManager contract
    RewardManager public rewardManager;
    
    // Authorized dApp contracts whitelist
    mapping(address => bool) public authorizedDApps;
    
    // Processed transactions (prevent replay attacks)
    mapping(bytes32 => bool) public processedTransactions;
    
    // Last action time per user/dApp/action (for cooldowns)
    mapping(address => mapping(string => uint256)) public lastActionTime;
    
    // Maximum action value (prevent excessive rewards)
    uint256 public maxActionValue;
    
    // Maximum reward per action type
    mapping(string => uint256) public maxRewardPerAction;
    
    // Cooldown period per action type (in seconds)
    mapping(string => uint256) public cooldownPeriods;
    
    // Default cooldown period (1 hour)
    uint256 public defaultCooldownPeriod = 3600;
    
    // Usage event structure
    struct UsageEvent {
        address user;
        address dAppContract;
        uint256 dAppId;
        string actionType;
        uint256 timestamp;
        bytes32 txHash;
        uint256 nonce;
    }
    
    // Track events per user
    mapping(address => UsageEvent[]) public userEvents;
    
    // Track events per dApp
    mapping(address => UsageEvent[]) public dAppEvents;
    
    // Event counter
    uint256 public totalEvents;
    
    // Events
    event UsageEventRecorded(
        address indexed user,
        address indexed dAppContract,
        uint256 indexed dAppId,
        string actionType,
        uint256 timestamp,
        bytes32 txHash
    );
    event RewardDistributed(
        address indexed user,
        address indexed dAppContract,
        uint256 rewardAmount
    );
    event DAppAuthorized(address indexed dAppContract, bool authorized);
    event RewardManagerUpdated(address indexed oldManager, address indexed newManager);
    event MaxActionValueUpdated(uint256 oldValue, uint256 newValue);
    event MaxRewardUpdated(string indexed actionType, uint256 oldValue, uint256 newValue);
    event CooldownPeriodUpdated(string indexed actionType, uint256 oldValue, uint256 newValue);
    
    /**
     * @dev Modifier to ensure only authorized dApp contracts can call
     */
    modifier onlyAuthorizedDApp() {
        require(authorizedDApps[msg.sender], "SecureProofOfUtility: Unauthorized dApp");
        _;
    }
    
    /**
     * @dev Constructor
     * @param _rewardManager Address of RewardManager contract
     * @param _maxActionValue Maximum action value allowed
     */
    constructor(address _rewardManager, uint256 _maxActionValue) Ownable(msg.sender) {
        require(_rewardManager != address(0), "SecureProofOfUtility: Invalid reward manager");
        require(_maxActionValue > 0, "SecureProofOfUtility: Invalid max action value");
        
        rewardManager = RewardManager(_rewardManager);
        maxActionValue = _maxActionValue;
    }
    
    /**
     * @dev Authorize a dApp contract (only owner)
     * @param dAppContract Address of the dApp contract
     */
    function authorizeDApp(address dAppContract) external onlyOwner {
        require(dAppContract != address(0), "SecureProofOfUtility: Invalid dApp contract");
        authorizedDApps[dAppContract] = true;
        emit DAppAuthorized(dAppContract, true);
    }
    
    /**
     * @dev Revoke authorization for a dApp contract (only owner)
     * @param dAppContract Address of the dApp contract
     */
    function revokeDApp(address dAppContract) external onlyOwner {
        require(dAppContract != address(0), "SecureProofOfUtility: Invalid dApp contract");
        authorizedDApps[dAppContract] = false;
        emit DAppAuthorized(dAppContract, false);
    }
    
    /**
     * @dev Verify transaction exists on-chain and matches expected parameters
     * @param txHash Transaction hash to verify
     * @param expectedUser Expected user address
     * @param expectedValue Expected transaction value
     * @return isValid Whether the transaction is valid
     * 
     * Note: This is a simplified verification. In production, you would:
     * - Query the blockchain for transaction details
     * - Verify transaction sender matches expectedUser
     * - Verify transaction value matches expectedValue
     * - Verify transaction was successful
     * - This may require an oracle or off-chain verification service
     */
    function verifyTransaction(
        bytes32 txHash,
        address expectedUser,
        uint256 expectedValue
    ) internal view returns (bool) {
        // Basic validation - transaction hash must be non-zero
        require(txHash != bytes32(0), "SecureProofOfUtility: Invalid transaction hash");
        
        // In a production environment, you would:
        // 1. Query the blockchain RPC for transaction details
        // 2. Verify tx.from == expectedUser
        // 3. Verify tx.value == expectedValue
        // 4. Verify tx.status == success
        // 
        // For now, we rely on the fact that only authorized dApps can call this,
        // and they should only call it after verifying the transaction themselves.
        // Additional on-chain verification can be added via an oracle.
        
        return true; // Simplified for now - should be enhanced with oracle/verification service
    }
    
    /**
     * @dev Record usage and distribute reward (called by authorized dApp contracts)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     * @param actionValue Value of the action (for reward calculation)
     * @param txHash Transaction hash for verification
     * @param nonce Nonce for replay protection
     */
    function recordUsageAndReward(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType,
        uint256 actionValue,
        bytes32 txHash,
        uint256 nonce
    ) public onlyAuthorizedDApp whenNotPaused nonReentrant {
        require(user != address(0), "SecureProofOfUtility: Invalid user");
        require(dAppContract != address(0), "SecureProofOfUtility: Invalid dApp contract");
        require(dAppContract == msg.sender, "SecureProofOfUtility: dApp contract mismatch");
        require(txHash != bytes32(0), "SecureProofOfUtility: Invalid transaction hash");
        require(actionValue > 0 && actionValue <= maxActionValue, "SecureProofOfUtility: Invalid action value");
        
        // Verify transaction occurred (simplified - should be enhanced with oracle)
        require(
            verifyTransaction(txHash, user, actionValue),
            "SecureProofOfUtility: Transaction verification failed"
        );
        
        // Prevent replay attacks
        bytes32 replayKey = keccak256(abi.encodePacked(txHash, nonce, user, dAppContract));
        require(!processedTransactions[replayKey], "SecureProofOfUtility: Transaction already processed");
        processedTransactions[replayKey] = true;
        
        // Rate limiting / cooldown protection
        bytes32 actionKey = keccak256(abi.encodePacked(user, dAppContract, actionType));
        uint256 cooldownPeriod = cooldownPeriods[actionType] > 0 
            ? cooldownPeriods[actionType] 
            : defaultCooldownPeriod;
        
        require(
            block.timestamp >= lastActionTime[user][actionType] + cooldownPeriod,
            "SecureProofOfUtility: Cooldown active"
        );
        lastActionTime[user][actionType] = block.timestamp;
        
        // Record usage event
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp,
            txHash: txHash,
            nonce: nonce
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp, txHash);
        
        // Distribute reward if actionValue > 0
        if (actionValue > 0) {
            // Check maximum reward per action type
            uint256 maxReward = maxRewardPerAction[actionType];
            if (maxReward > 0) {
                // Calculate expected reward (simplified - actual calculation in RewardManager)
                // This is a safety check - RewardManager will do the actual calculation
                require(actionValue <= maxReward, "SecureProofOfUtility: Action value exceeds maximum reward");
            }
            
            rewardManager.distributeReward(user, dAppContract, actionValue);
            emit RewardDistributed(user, dAppContract, actionValue);
        }
    }
    
    /**
     * @dev Record usage without reward (for tracking purposes)
     * @param user Address of the user
     * @param dAppContract Address of the dApp contract
     * @param dAppId ID of the dApp
     * @param actionType Type of action performed
     * @param txHash Transaction hash
     * @param nonce Nonce for replay protection
     */
    function recordUsage(
        address user,
        address dAppContract,
        uint256 dAppId,
        string memory actionType,
        bytes32 txHash,
        uint256 nonce
    ) public onlyAuthorizedDApp whenNotPaused {
        require(user != address(0), "SecureProofOfUtility: Invalid user");
        require(dAppContract != address(0), "SecureProofOfUtility: Invalid dApp contract");
        require(dAppContract == msg.sender, "SecureProofOfUtility: dApp contract mismatch");
        require(txHash != bytes32(0), "SecureProofOfUtility: Invalid transaction hash");
        
        // Prevent replay attacks
        bytes32 replayKey = keccak256(abi.encodePacked(txHash, nonce, user, dAppContract));
        require(!processedTransactions[replayKey], "SecureProofOfUtility: Transaction already processed");
        processedTransactions[replayKey] = true;
        
        // Record usage event
        UsageEvent memory event_ = UsageEvent({
            user: user,
            dAppContract: dAppContract,
            dAppId: dAppId,
            actionType: actionType,
            timestamp: block.timestamp,
            txHash: txHash,
            nonce: nonce
        });
        
        userEvents[user].push(event_);
        dAppEvents[dAppContract].push(event_);
        totalEvents++;
        
        emit UsageEventRecorded(user, dAppContract, dAppId, actionType, block.timestamp, txHash);
    }
    
    /**
     * @dev Get user's usage events
     * @param user User address
     * @return Array of usage events
     */
    function getUserEvents(address user) external view returns (UsageEvent[] memory) {
        return userEvents[user];
    }
    
    /**
     * @dev Get dApp's usage events
     * @param dAppContract dApp contract address
     * @return Array of usage events
     */
    function getDAppEvents(address dAppContract) external view returns (UsageEvent[] memory) {
        return dAppEvents[dAppContract];
    }
    
    /**
     * @dev Get user's event count
     * @param user User address
     * @return Event count
     */
    function getUserEventCount(address user) external view returns (uint256) {
        return userEvents[user].length;
    }
    
    /**
     * @dev Set maximum action value (only owner)
     * @param _maxActionValue New maximum action value
     */
    function setMaxActionValue(uint256 _maxActionValue) external onlyOwner {
        require(_maxActionValue > 0, "SecureProofOfUtility: Invalid max action value");
        uint256 oldValue = maxActionValue;
        maxActionValue = _maxActionValue;
        emit MaxActionValueUpdated(oldValue, _maxActionValue);
    }
    
    /**
     * @dev Set maximum reward per action type (only owner)
     * @param actionType Action type
     * @param maxReward Maximum reward for this action type
     */
    function setMaxRewardPerAction(string memory actionType, uint256 maxReward) external onlyOwner {
        uint256 oldValue = maxRewardPerAction[actionType];
        maxRewardPerAction[actionType] = maxReward;
        emit MaxRewardUpdated(actionType, oldValue, maxReward);
    }
    
    /**
     * @dev Set cooldown period for action type (only owner)
     * @param actionType Action type
     * @param cooldownPeriod Cooldown period in seconds
     */
    function setCooldownPeriod(string memory actionType, uint256 cooldownPeriod) external onlyOwner {
        uint256 oldValue = cooldownPeriods[actionType];
        cooldownPeriods[actionType] = cooldownPeriod;
        emit CooldownPeriodUpdated(actionType, oldValue, cooldownPeriod);
    }
    
    /**
     * @dev Set default cooldown period (only owner)
     * @param _defaultCooldownPeriod Default cooldown period in seconds
     */
    function setDefaultCooldownPeriod(uint256 _defaultCooldownPeriod) external onlyOwner {
        defaultCooldownPeriod = _defaultCooldownPeriod;
    }
    
    /**
     * @dev Update reward manager (only owner)
     * @param _rewardManager New reward manager address
     */
    function setRewardManager(address _rewardManager) external onlyOwner {
        require(_rewardManager != address(0), "SecureProofOfUtility: Invalid reward manager");
        address oldManager = address(rewardManager);
        rewardManager = RewardManager(_rewardManager);
        emit RewardManagerUpdated(oldManager, _rewardManager);
    }
    
    /**
     * @dev Pause contract (only owner)
     */
    function pause() external onlyOwner {
        _pause();
    }
    
    /**
     * @dev Unpause contract (only owner)
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/SimplePayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./FeeCollector.sol";
import "./IFeeRouter.sol";

/**
 * @title SimplePayment
 * @dev Simple payment dApp with automatic fee collection
 * @notice First dApp demonstrating the fee collection pattern
 */
contract SimplePayment is Ownable, ReentrancyGuard {
    // Fee collector contract (used when feeRouter is not set)
    FeeCollector public feeCollector;
    // Optional: when set, fees go through FeeRouter for Revenue Tree distribution
    IFeeRouter public feeRouter;

    // Fee percentage (basis points, 10000 = 100%)
    uint256 public feePercentage;

    // Payment events
    event PaymentSent(
        address indexed from,
        address indexed to,
        uint256 amount,
        uint256 fee,
        uint256 timestamp
    );
    event FeeCollected(uint256 amount, uint256 timestamp);
    event FeeCollectorUpdated(address indexed oldCollector, address indexed newCollector);
    event FeeRouterUpdated(address indexed oldRouter, address indexed newRouter);
    event FeePercentageUpdated(uint256 oldPercentage, uint256 newPercentage);

    /**
     * @dev Constructor sets fee collector and fee percentage
     * @param _feeCollector Address of the FeeCollector contract
     * @param _feePercentage Fee percentage in basis points (e.g., 100 = 1%)
     */
    constructor(address _feeCollector, uint256 _feePercentage) Ownable(msg.sender) {
        require(_feeCollector != address(0), "SimplePayment: Invalid fee collector");
        require(_feePercentage <= 1000, "SimplePayment: Fee cannot exceed 10%");
        feeCollector = FeeCollector(_feeCollector);
        feePercentage = _feePercentage;
    }

    /**
     * @dev Send payment to a recipient with automatic fee deduction
     * @param _recipient Address to receive the payment
     * @notice Automatically deducts fee and sends to treasury
     */
    function sendPayment(address _recipient) external payable nonReentrant {
        require(_recipient != address(0), "SimplePayment: Invalid recipient");
        require(msg.value > 0, "SimplePayment: Amount must be greater than 0");

        uint256 fee = (msg.value * feePercentage) / 10000;
        uint256 paymentAmount = msg.value - fee;

        // Send fee: via FeeRouter (Revenue Tree + treasury + GRID + points) or FeeCollector only
        if (fee > 0) {
            if (address(feeRouter) != address(0)) {
                feeRouter.forwardFeeAndRevenueWithRewards{value: fee}(msg.sender, "dapp-payment", msg.value);
            } else {
                feeCollector.forwardFee{value: fee}();
            }
            emit FeeCollected(fee, block.timestamp);
        }

        // Send payment to recipient
        (bool success, ) = payable(_recipient).call{value: paymentAmount}("");
        require(success, "SimplePayment: Payment transfer failed");

        emit PaymentSent(msg.sender, _recipient, paymentAmount, fee, block.timestamp);
    }

    /**
     * @dev Update fee collector address
     * @param _feeCollector New fee collector address
     */
    function setFeeCollector(address _feeCollector) external onlyOwner {
        require(_feeCollector != address(0), "SimplePayment: Invalid fee collector");
        address oldCollector = address(feeCollector);
        feeCollector = FeeCollector(_feeCollector);
        emit FeeCollectorUpdated(oldCollector, _feeCollector);
    }

    /**
     * @dev Set FeeRouter for Revenue Tree; when set, fees use forwardFeeAndRevenue(payer) instead of FeeCollector.
     * @param _feeRouter Address of FeeRouter contract, or address(0) to use FeeCollector only
     */
    function setFeeRouter(address _feeRouter) external onlyOwner {
        address oldRouter = address(feeRouter);
        feeRouter = IFeeRouter(_feeRouter);
        emit FeeRouterUpdated(oldRouter, _feeRouter);
    }

    /**
     * @dev Update fee percentage
     * @param _feePercentage New fee percentage in basis points
     */
    function setFeePercentage(uint256 _feePercentage) external onlyOwner {
        require(_feePercentage <= 1000, "SimplePayment: Fee cannot exceed 10%");
        uint256 oldPercentage = feePercentage;
        feePercentage = _feePercentage;
        emit FeePercentageUpdated(oldPercentage, _feePercentage);
    }

    /**
     * @dev Calculate fee for a given amount
     * @param _amount Amount to calculate fee for
     * @return Fee amount
     */
    function calculateFee(uint256 _amount) external view returns (uint256) {
        return (_amount * feePercentage) / 10000;
    }

    /**
     * @dev Get payment amount after fee deduction
     * @param _amount Total amount
     * @return Payment amount after fee
     */
    function getPaymentAmount(uint256 _amount) external view returns (uint256) {
        uint256 fee = (_amount * feePercentage) / 10000;
        return _amount - fee;
    }
}

contracts/SubscriptionManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./PlatformSubscription.sol";
import "./DAppSubscription.sol";

/**
 * @title SubscriptionManager
 * @dev Unified manager for both platform and per-dApp subscriptions
 * @notice Provides a single interface to check subscription status across both systems
 */
contract SubscriptionManager is Ownable {
    // Platform subscription contract
    PlatformSubscription public platformSubscription;

    // Per-dApp subscription contract
    DAppSubscription public dAppSubscription;

    // Events
    event PlatformSubscriptionUpdated(
        address indexed oldContract,
        address indexed newContract
    );
    event DAppSubscriptionUpdated(
        address indexed oldContract,
        address indexed newContract
    );

    /**
     * @dev Constructor sets up subscription contracts
     * @param _platformSubscription Address of PlatformSubscription contract
     * @param _dAppSubscription Address of DAppSubscription contract
     */
    constructor(
        address _platformSubscription,
        address _dAppSubscription
    ) Ownable(msg.sender) {
        require(
            _platformSubscription != address(0),
            "SubscriptionManager: Invalid platform subscription address"
        );
        require(
            _dAppSubscription != address(0),
            "SubscriptionManager: Invalid dApp subscription address"
        );

        platformSubscription = PlatformSubscription(_platformSubscription);
        dAppSubscription = DAppSubscription(_dAppSubscription);
    }

    /**
     * @dev Check if a user has access to a dApp
     * @notice Returns true if user has platform subscription OR per-dApp subscription
     * @param _user User address
     * @param _dAppContract dApp contract address (optional, 0x0 for platform-only check)
     * @return bool True if user has access
     */
    function hasAccess(
        address _user,
        address _dAppContract
    ) external view returns (bool) {
        // Check platform subscription first (gives access to all dApps)
        try platformSubscription.isSubscribed(_user) returns (bool platformSubscribed) {
            if (platformSubscribed) {
                return true;
            }
        } catch {
            // If check fails, continue to per-dApp check
        }

        // Check per-dApp subscription if dApp contract is provided
        if (_dAppContract != address(0)) {
            try dAppSubscription.isSubscribed(_user, _dAppContract) returns (
                bool dAppSubscribed
            ) {
                if (dAppSubscribed) {
                    return true;
                }
            } catch {
                // If check fails, return false
            }
        }

        return false;
    }

    /**
     * @dev Check if user has platform subscription
     * @param _user User address
     * @return bool True if has platform subscription
     */
    function hasPlatformSubscription(address _user) external view returns (bool) {
        try platformSubscription.isSubscribed(_user) returns (bool subscribed) {
            return subscribed;
        } catch {
            return false;
        }
    }

    /**
     * @dev Check if user has per-dApp subscription
     * @param _user User address
     * @param _dAppContract dApp contract address
     * @return bool True if has per-dApp subscription
     */
    function hasDAppSubscription(
        address _user,
        address _dAppContract
    ) external view returns (bool) {
        try dAppSubscription.isSubscribed(_user, _dAppContract) returns (
            bool subscribed
        ) {
            return subscribed;
        } catch {
            return false;
        }
    }

    /**
     * @dev Check if user is in grace period for platform subscription
     * @param _user User address
     * @return bool True if in grace period
     */
    function isInPlatformGracePeriod(address _user) external view returns (bool) {
        try platformSubscription.isInGracePeriod(_user) returns (bool inGracePeriod) {
            return inGracePeriod;
        } catch {
            return false;
        }
    }

    /**
     * @dev Get platform subscription expiry timestamp
     * @param _user User address
     * @return uint256 Expiry timestamp (0 if not subscribed)
     */
    function getPlatformExpiry(address _user) external view returns (uint256) {
        try platformSubscription.getExpiryTimestamp(_user) returns (uint256 expiry) {
            return expiry;
        } catch {
            return 0;
        }
    }

    /**
     * @dev Get per-dApp subscription expiry timestamp
     * @param _user User address
     * @param _dAppContract dApp contract address
     * @return uint256 Expiry timestamp (0 if not subscribed)
     */
    function getDAppExpiry(
        address _user,
        address _dAppContract
    ) external view returns (uint256) {
        try dAppSubscription.getExpiryTimestamp(_user, _dAppContract) returns (
            uint256 expiry
        ) {
            return expiry;
        } catch {
            return 0;
        }
    }

    /**
     * @dev Update PlatformSubscription contract address (only owner)
     * @param _platformSubscription New PlatformSubscription contract address
     */
    function setPlatformSubscription(address _platformSubscription) external onlyOwner {
        require(
            _platformSubscription != address(0),
            "SubscriptionManager: Invalid platform subscription address"
        );
        address oldContract = address(platformSubscription);
        platformSubscription = PlatformSubscription(_platformSubscription);
        emit PlatformSubscriptionUpdated(oldContract, _platformSubscription);
    }

    /**
     * @dev Update DAppSubscription contract address (only owner)
     * @param _dAppSubscription New DAppSubscription contract address
     */
    function setDAppSubscription(address _dAppSubscription) external onlyOwner {
        require(
            _dAppSubscription != address(0),
            "SubscriptionManager: Invalid dApp subscription address"
        );
        address oldContract = address(dAppSubscription);
        dAppSubscription = DAppSubscription(_dAppSubscription);
        emit DAppSubscriptionUpdated(oldContract, _dAppSubscription);
    }

    /**
     * @dev Get comprehensive subscription status for a user
     * @param _user User address
     * @param _dAppContract dApp contract address (optional)
     * @return platformSubscribed Whether user has platform subscription
     * @return platformExpiry Platform subscription expiry timestamp
     * @return dAppSubscribed Whether user has per-dApp subscription
     * @return dAppExpiry Per-dApp subscription expiry timestamp
     * @return userHasAccess Whether user has access to the dApp
     */
    function getSubscriptionStatus(
        address _user,
        address _dAppContract
    )
        external
        view
        returns (
            bool platformSubscribed,
            uint256 platformExpiry,
            bool dAppSubscribed,
            uint256 dAppExpiry,
            bool userHasAccess
        )
    {
        // Platform subscription
        try platformSubscription.isSubscribed(_user) returns (bool subscribed) {
            platformSubscribed = subscribed;
        } catch {
            platformSubscribed = false;
        }

        try platformSubscription.getExpiryTimestamp(_user) returns (uint256 expiry) {
            platformExpiry = expiry;
        } catch {
            platformExpiry = 0;
        }

        // Per-dApp subscription
        if (_dAppContract != address(0)) {
            try dAppSubscription.isSubscribed(_user, _dAppContract) returns (
                bool subscribed
            ) {
                dAppSubscribed = subscribed;
            } catch {
                dAppSubscribed = false;
            }

            try dAppSubscription.getExpiryTimestamp(_user, _dAppContract) returns (
                uint256 expiry
            ) {
                dAppExpiry = expiry;
            } catch {
                dAppExpiry = 0;
            }
        }

        // Overall access
        userHasAccess = platformSubscribed || dAppSubscribed;
    }
}

contracts/tGRID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title tGRID
 * @dev Test GRID token for IGRA Galleon Testnet (38836). Same economics as GRID; mintable by owner for testnet use.
 * @notice Max supply 10B tGRID; pre-minted to reward vault; owner can mint more for testing.
 */
contract tGRID is ERC20, Ownable, ReentrancyGuard {
    uint256 public constant MAX_SUPPLY = 10_000_000_000 * 10**18;

    address public rewardVault;
    uint256 public totalBurned;

    event TokensBurned(address indexed from, uint256 amount);
    event RewardVaultUpdated(address indexed oldVault, address indexed newVault);
    event Minted(address indexed to, uint256 amount);

    constructor(address _rewardVault) ERC20("Test GRID Token", "tGRID") Ownable(msg.sender) {
        require(_rewardVault != address(0), "tGRID: Invalid reward vault");
        rewardVault = _rewardVault;
        _mint(_rewardVault, MAX_SUPPLY);
    }

    /**
     * @dev Mint additional tokens (testnet only; for reward distribution top-ups).
     */
    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
        emit Minted(to, amount);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
        totalBurned += amount;
        emit TokensBurned(msg.sender, amount);
    }

    function burnFrom(address from, uint256 amount) external {
        _spendAllowance(from, msg.sender, amount);
        _burn(from, amount);
        totalBurned += amount;
        emit TokensBurned(from, amount);
    }

    function setRewardVault(address _rewardVault) external onlyOwner {
        require(_rewardVault != address(0), "tGRID: Invalid reward vault");
        address oldVault = rewardVault;
        rewardVault = _rewardVault;
        emit RewardVaultUpdated(oldVault, _rewardVault);
    }

    function circulatingSupply() external view returns (uint256) {
        return totalSupply() - totalBurned;
    }

    function burnPercentage() external view returns (uint256) {
        if (MAX_SUPPLY == 0) return 0;
        return (totalBurned * 10000) / MAX_SUPPLY;
    }
}

